update oa_salary_config
work_start_time = #{workStartTime}, work_end_time = #{workEndTime}, work_hours_per_day = #{workHoursPerDay}, late_penalty_per_min = #{latePenaltyPerMin}, early_penalty_per_min = #{earlyPenaltyPerMin}, absent_penalty_per_day = #{absentPenaltyPerDay}, overtime_pay_per_hour = #{overtimePayPerHour}, update_by = #{updateBy}, update_time = sysdate()
where config_id = #{configId}
